{"command": "cd /testbed && PYTHONPATH=tests:. DJANGO_SETTINGS_MODULE=test_sqlite python - <<'PY'
import django
django.setup()
from django.contrib.admindocs.utils import trim_docstring, parse_docstring, parse_rst
s = 'Title\n\n    Body line one.\n    Body line two.\n    '
print(repr(trim_docstring(s)))
try:
    print(parse_rst(trim_docstring(s), 'view', 'view:test'))
except Exception as e:
    import traceback; traceback.print_exc()
# with fixed expected manually dedented
try:
    print(parse_rst('Title\n\nBody line one.\nBody line two.', 'view', 'view:test'))
except Exception as e:
    import traceback; traceback.print_exc()
PY"}

